-- The intent parser requires literal values from the question, so section URLs could never be bound.
-- Generated by gateway/scripts/prepare-rapidapi-news.mjs from live 2026-09-14 section captures.
BEGIN;

SELECT pg_advisory_xact_lock(hashtext('apiosk-rapidapi-news'));

DO $guard$ BEGIN IF NOT EXISTS(SELECT 1 FROM providers.api_endpoints e JOIN providers.apis a ON a.id=e.api_id WHERE e.id='f38a340c-59c3-4fd9-a8a1-0bbe4f0ee78b' AND a.slug='reuters' AND e.path='/category' AND e.method='GET' AND e.active AND e.price=0.047259) THEN RAISE EXCEPTION 'Reuters /category endpoint changed'; END IF; END $guard$;

UPDATE catalog.capability_execution_contracts SET status='retired',notes=coalesce(notes,'')||'; retired 20260914: section URL cannot be a literal question value' WHERE capability_slug='news.reuters-section' AND endpoint_id='f38a340c-59c3-4fd9-a8a1-0bbe4f0ee78b';

UPDATE catalog.capabilities SET status='retired' WHERE slug='news.reuters-section';

UPDATE catalog.fact_types SET status='retired' WHERE slug='news.reuters_section_url' AND NOT EXISTS(SELECT 1 FROM catalog.capability_execution_contracts WHERE status='active' AND requires @> '[{"fact_type":"news.reuters_section_url"}]');

