UPDATE providers.apis SET listing_metadata=listing_metadata || '{"coverage_notice":"Read operations checked live on 2026-09-14: latest headlines, keyword headline search, the section list and headlines for 18 sections (World, Africa, Americas, Asia Pacific, China, Europe, India, Middle East, UK, US, Business, Markets, Technology, Legal, Sustainability, Science, Sports, Lifestyle). At most 12 headlines per call; search results carry no date field and keyword matching is loose. Breakingviews returned HTTP 502 and is not offered. The provider /details route is not offered because it returns text synthesized from the URL instead of the article. The upstream plan also limits requests per second.","production_probe":{"probed_on":"2026-09-14","evidence":"evidence/2026-09-14/rapidapi-news/measurements.json","operations_connected":21,"operations_measured":23,"gateway_paid_checks":5}}'::jsonb,long_description='Read operations checked live on 2026-09-14: latest headlines, keyword headline search, the section list and headlines for 18 sections (World, Africa, Americas, Asia Pacific, China, Europe, India, Middle East, UK, US, Business, Markets, Technology, Legal, Sustainability, Science, Sports, Lifestyle). At most 12 headlines per call; search results carry no date field and keyword matching is loose. Breakingviews returned HTTP 502 and is not offered. The provider /details route is not offered because it returns text synthesized from the URL instead of the article. The upstream plan also limits requests per second.' WHERE slug='reuters' AND is_platform_owned;

DO $verify$ BEGIN
 IF (SELECT count(*) FROM catalog.capability_execution_contracts WHERE endpoint_id='f38a340c-59c3-4fd9-a8a1-0bbe4f0ee78b' AND status='active' AND capability_slug LIKE 'news.reuters-section-%')<>18
  OR EXISTS(SELECT 1 FROM catalog.capability_execution_contracts WHERE capability_slug='news.reuters-section' AND status='active') THEN
  RAISE EXCEPTION 'Reuters section contract invariant failed'; END IF;
END $verify$;

COMMIT;
